class Command {
  execute() {}
}
class AddCommand extends Command {
  constructor(receiver, value) { super(); this.receiver = receiver; this.value = value; }
  execute() { this.receiver.value += this.value; }
}
const obj = { value: 0 };
new AddCommand(obj, 5).execute();
console.log(obj.value);
